package com.tainted.authuser.blackbox;

import static com.tainted.authuser.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller AuthController (src/main/java/com/tainted/authuser/web/AuthController.java)
 * @target-api POST /api/v1/auth/guest
 *
 * AuthController.guest -> AuthService.guest(): no request params, no @Valid body.
 * generate-test-plan heuristic proposed ATC_code400 ("General Bad Request") but the
 * handler takes zero input and performs no validation -- source review (AuthController,
 * AuthService.guest) confirms no client-triggerable 400/error branch exists, and
 * generate-vtc-from-red-params confirms zero RED params / zero API-level mutations
 * (anchor param required, none present). That heuristic ATC is therefore excluded as a
 * false positive rather than fabricated to satisfy the checklist.
 * Each call creates a brand-new UserAccount row with a server-generated UUID id and
 * externalId (guest:<uuid>), so the created row cannot be targeted by setup/teardown or
 * dbAssertions (no ${SEED} is known ahead of the call) -- no fixtures are used, and
 * dynamic fields (accessToken) are verified with notNullValue() since their value is
 * genuinely unpredictable; displayName is deterministic (AuthService.DISPLAY_NAME) and
 * is verified with equalTo().
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthGuestBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/auth-guest-teardown.sql", p);
        executeSqlTemplate("sql/auth-guest-setup.sql", p);
    }

    @Test
    void NTC_guest_returnsTokenAndDisplayName(TestInfo info) {
        // Happy path: guest() always succeeds, returns new token + constant display name
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .post("/api/v1/auth/guest")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
        } finally {
            executeSqlTemplate("sql/auth-guest-teardown.sql", p);
        }
    }

    @Test
    void NTC_guest_repeatedCallIndependentlySucceeds(TestInfo info) {
        // Second independent call: no shared state/session required, still succeeds with its own new user+token
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
            .when()
                    .post("/api/v1/auth/guest")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
        } finally {
            executeSqlTemplate("sql/auth-guest-teardown.sql", p);
        }
    }

    @Test
    void NTC_guest_ignoresUnexpectedBody(TestInfo info) {
        // guest() takes no @RequestBody -- an unexpected JSON body must be ignored, not rejected
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"unexpected\": \"field\"}")
            .when()
                    .post("/api/v1/auth/guest")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("accessToken", notNullValue());
        } finally {
            executeSqlTemplate("sql/auth-guest-teardown.sql", p);
        }
    }
}

