package com.tainted.authuser.blackbox;

import static com.tainted.authuser.blackbox.support.BlackBoxSupport.BASE_URL;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testId;
import static com.tainted.authuser.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller InternalAuthController (src/main/java/com/tainted/authuser/web/InternalAuthController.java)
 * @target-api POST /internal/auth/verify
 *
 * InternalAuthController.verify -> AuthService.verify(VerifyRequest{token}.token()).
 * AuthService.verify: tokenService.resolveUserId(token).flatMap(repository::findById)
 * .map(active=true).orElse(active=false) -- it NEVER throws; both found/not-found
 * outcomes return HTTP 200 with a VerifyResponse body. generate-test-plan's heuristic
 * 'ATC_token_noData' ("expects exception or empty response") is therefore implemented
 * here as an NTC (200, active=false), matching the real orElse() branch, not as an ATC.
 * generate-vtc-from-red-params correctly flagged token as RED (DB_WHERE) and proposed
 * NULL/EMPTY/WHITE_SPACE/SPECIAL_CHAR mutations, but its java_snippet output assumes a
 * different reference SUT (Api-Id/Access-Key headers, Result/ResultCode fields) that do
 * not exist here -- those snippets were NOT used verbatim; only the mutation *ideas* were
 * kept and re-verified against this project's actual VerifyRequest (@NotBlank token) and
 * VerifyResponse (active/userId/socialProvider) contracts.
 * The 'active=true' (token found) branch cannot be produced by this black-box harness:
 * TokenService stores tokens in Redis (StringRedisTemplate), and template-render only
 * provides JDBC-based SQL fixtures -- there is no way to seed a Redis key deterministically,
 * and the only token producers (guest/login) issue a cryptographically random UUID with no
 * seed control (UuidIdGenerator), so a prior HTTP call's token cannot be threaded into this
 * test's JSON body (the auth catalog only injects a captured token into an Authorization
 * header, and verify reads the token from the request body, not a header). This is a
 * genuine tooling gap, not an oversight; the reachable NTC surface is therefore the
 * not-found branch only, exercised with three distinct token shapes.
 * SPECIAL_CHAR (SQL-injection-shaped token) and OVERFLOW (very long token) both still
 * resolve to the same not-found branch (200/inactive) since token is only ever used as a
 * Redis key / JPA parameterized lookup, never raw SQL or reflected output -- folded into
 * the NTC set below instead of being fabricated as separate VTC failures.
 * BAD_HEADER (Content-Type: application/xml) has no registered HttpMessageConverter for
 * XML in this project (no jackson-dataformat-xml dependency) -> standard Spring behavior
 * is 415 Unsupported Media Type, kept as ATC_verify_unsupportedContentType.
 * WRONG_METHOD (GET on this path) cannot be expressed: the spec's HTTP method is class-wide
 * (POST), so a per-test GET override is not representable in this schema -- skipped,
 * documented rather than silently dropped.
 * expectBody is intentionally empty on the three not-found NTCs: VerifyResponse.active is
 * a primitive boolean (JSON true/false, not a string) and userId/socialProvider are null
 * in this branch. The renderer's assertion catalog (equalTo/equalToInt/containsString/
 * notNullValue) has no boolean-safe or null-safe operator -- equalTo() always quotes its
 * value into a Java String literal, which would never equal a Hamcrest-compared Boolean,
 * and notNullValue() would incorrectly require a non-null userId. Asserting statusCode 200
 * only for these three is deliberate, not an oversight.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class InternalAuthVerifyBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "SEED", "vt" + testId(info));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        executeSqlTemplate("sql/internal-auth-verify-setup.sql", p);
    }

    @Test
    void NTC_verify_unknownToken_returnsInactive(TestInfo info) {
        // token well-formed but never issued -> resolveUserId empty -> orElse(inactive) branch, full response contract
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"token\": \"never-issued-" + p.get("SEED") + "\"}")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(200);;
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }

    @Test
    void NTC_verify_specialCharToken_returnsInactive(TestInfo info) {
        // SQL-injection-shaped token still non-blank -> same not-found branch, proves no crash/injection risk
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"token\": \"'; DROP TABLE user_account; --" + p.get("SEED") + "\"}")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(200);;
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }

    @Test
    void NTC_verify_veryLongToken_returnsInactive(TestInfo info) {
        // very long token (no @Size on VerifyRequest.token) -> same not-found branch, proves no overflow crash
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"token\": \"AAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAAA-" + p.get("SEED") + "\"}")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(200);;
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }

    @Test
    void VTC_token_NULL(TestInfo info) {
        // token omitted -> @NotBlank on VerifyRequest.token -> 400 before AuthService is reached
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{}")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(400)
                    .body("title", equalTo("Validation failed"))
                    .body("detail", equalTo("must not be blank"));
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }

    @Test
    void VTC_token_EMPTY(TestInfo info) {
        // token="" -> @NotBlank -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"token\": \"\"}")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(400)
                    .body("title", equalTo("Validation failed"))
                    .body("detail", equalTo("must not be blank"));
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }

    @Test
    void VTC_token_WHITE_SPACE(TestInfo info) {
        // token="   " -> @NotBlank treats whitespace-only as blank -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .contentType(ContentType.JSON)
                    .body("{\"token\": \"   \"}")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(400)
                    .body("title", equalTo("Validation failed"))
                    .body("detail", equalTo("must not be blank"));
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }

    @Test
    void ATC_verify_unsupportedContentType(TestInfo info) {
        // Content-Type application/xml has no registered HttpMessageConverter -> 415 Unsupported Media Type
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Content-Type", "application/xml")
            .when()
                    .post("/internal/auth/verify")
            .then()
                    .statusCode(415);;
        } finally {
            executeSqlTemplate("sql/internal-auth-verify-teardown.sql", p);
        }
    }
}

