 * displayName/socialProvider are asserted with equalTo() (AuthService.DISPLAY_NAME is the
 * literal constant '익명' for every user including guests, and guest() always sets
 * provider='guest'). userId is asserted with notNullValue() only since it's a fresh random
 * UUID from UuidIdGenerator, never known ahead of the call.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class MeBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
);
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/me-teardown.sql", p);
        executeSqlTemplate("sql/me-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{}")
        .when().post("/api/v1/auth/guest")
        .then().statusCode(200)
        .extract().jsonPath().getString("accessToken");
    }

    @Test
    void NTC_me_returnsGuestProfile(TestInfo info) {
        // valid guest-issued token -> full MeResponse contract
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
            .when()
                    .get("/api/v1/me")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("socialProvider", equalTo("guest"))
                    .body("userId", notNullValue());
        } finally {
            executeSqlTemplate("sql/me-teardown.sql", p);
        }
    }

    @Test
    void NTC_me_toleratesExtraQueryParam(TestInfo info) {
        // me() declares no @RequestParam -- an unexpected query param must be ignored, not rejected
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .queryParam("debug", "1")
            .when()
                    .get("/api/v1/me")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("socialProvider", equalTo("guest"))
                    .body("userId", notNullValue());
        } finally {
            executeSqlTemplate("sql/me-teardown.sql", p);
        }
    }

    @Test
    void NTC_me_toleratesExtraHeader(TestInfo info) {
        // an unrelated extra header must not interfere with the Authorization-driven lookup
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .header("X-Trace-Id", "trace-abc-123")
            .when()
                    .get("/api/v1/me")
            .then()
                    .statusCode(200)
                    .body("displayName", equalTo("익명"))
                    .body("socialProvider", equalTo("guest"))
                    .body("userId", notNullValue());
        } finally {
            executeSqlTemplate("sql/me-teardown.sql", p);
        }
    }
}

